mapper.update:
UPDATE space_invitations
SET status = 'SUPERSEDED', updated_at = #{now}
WHERE space_id = #{spaceId} AND email_normalized = #{emailNormalized} AND status = 'PENDING'

UPDATE space_invitations
SET status = 'REVOKED', updated_at = #{now}
WHERE id = #{id} AND space_id = #{spaceId} AND status = 'PENDING'

UPDATE space_invitations
SET status = 'ACCEPTED', accepted_user_id = #{acceptedUserId}, accepted_at = #{now},
    updated_at = #{now}
WHERE id = #{id} AND space_id = #{spaceId}
  AND status = 'PENDING' AND expires_at > #{now}

